pub struct JsonRpcRequestRejection {
    pub id: RequestId,
    pub method: String,
    pub error: RpcError,
}

impl JsonRpcRequestRejection {
    pub fn into_response(self) -> JsonRpcResponse {
        JsonRpcResponse {
            jsonrpc: "2.0".to_string(),
            id: Some(self.id),
            response: JsonRpcResponsePayload::Error { error: self.error },
        }
    }
}

